"""Paradoxes: seven EL2 studies about useful enemies and unexpected costs.

These are additions to the existing catalogue.  The real GDScript puzzle lab
validates the reference lines and bounded opponent replies; optional alternate
solutions record genuinely different uses of the same position's resources.
"""
from puzzle_authoring import hero, unit, state, enchant, puzzle, cast, ability, attack, block, end


_ROLES = {
    "after_fire": (("The Ash Gardener", "The Toll Collector"), ("Садовник пепла", "Сборщик пошлин")),
    "last_spell": (("The Silent Archivist", "The Last Witness"), ("Безмолвный архивариус", "Последний свидетель")),
    "empty_room": (("The Room Keeper", "The Fog Collector"), ("Хранитель комнат", "Собиратель тумана")),
    "stolen_reply": (("The Careless Courier", "The Confident Thief"), ("Беспечный курьер", "Самоуверенный вор")),
    "every_door": (("The Keeper of Doors", "The Relentless Host"), ("Хранитель дверей", "Неумолимый хозяин")),
    "borrowed_kin": (("The Kin Accountant", "The Rat Breeder"), ("Счётчик родства", "Крысиный заводчик")),
    "wanted_fog": (("The Patient Wolf Tamer", "The Keeper of Mist"), ("Терпеливая укротительница", "Хранитель тумана")),
}


def _study(slug, title, title_ru, category, category_ru, level, turns, position,
           briefing, briefing_ru, hints, hints_ru, explanation, explanation_ru,
           solution, objective=None, refutations=None, alternative_solutions=None):
    value = puzzle("el2", "paradox_" + slug, title, category, level, turns, position,
        briefing, hints, explanation, solution, objective=objective,
        title_ru=title_ru, category_ru=category_ru, briefing_ru=briefing_ru,
        hints_ru=hints_ru, explanation_ru=explanation_ru,
        hero_names=list(_ROLES[slug][0]), hero_names_ru=list(_ROLES[slug][1]),
        refutations=refutations or [])
    if alternative_solutions:
        value["alternative_solutions"] = alternative_solutions
    return value


